import {createShell,ObserverPlayer} from './shared/observer.js';
import {DURATION,stages,stateAt,contactGeometry,jointPath,clamp} from './model.js';
const shell=createShell({title:'倒裝接合｜晶粒翻過來，怎麼接到基板？',sceneLabel:'追蹤晶粒翻轉、焊點形成與底填膠的局部剖視動畫'});
const svg=shell.svg;
const colors={die:'#AABFCD',front:'#D8E5EC',back:'#91AABA',pad:'#D5B580',solder:'#BAC5CF',hot:'#DBB99F',underfill:'#ADD4C8',cured:'#8CBDAF',flux:'#B9A3CD'};
svg.innerHTML=`<defs><pattern id="cure-pattern" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M-2 9L9-2 M7 11L11 7" stroke="#628F81" stroke-width=".7" opacity=".38"/></pattern><mask id="gap-mask" maskUnits="userSpaceOnUse"><rect id="gap-white" fill="white"/><g id="joint-cutouts" fill="black"/></mask><clipPath id="world-clip"><rect id="clip-box"/></clipPath></defs>
<text id="view-label" class="small-label" x="16" y="24">局部剖視 · 非實際比例</text><text id="batch-label" class="small-label" text-anchor="end" y="24"/>
<g clip-path="url(#world-clip)"><g id="assembly"><g id="substrate"/><g id="alignment"/><g id="fluid" mask="url(#gap-mask)"><path id="fluid-body"/><path id="cure-texture" fill="url(#cure-pattern)"/><path id="fluid-front" fill="none" stroke="#609B89" stroke-width="1.7"/></g><g id="edge-fillets"/><g id="bumps-back"/><g id="chip-faces"/><g id="bumps-front"/><g id="identity-marks"/><g id="electric-path"/><g id="object-labels"/></g><g id="dispenser"/></g><g id="process-note"/><text id="empty-label" class="label" text-anchor="middle"/>`;
const el=id=>shell.get(id),set=(id,attrs)=>{for(const [k,v]of Object.entries(attrs))el(id).setAttribute(k,v);};
const text=(x,y,value,cls='label',anchor='start')=>`<text class="${cls}" x="${x}" y="${y}" text-anchor="${anchor}">${value}</text>`;
let layout,player,selected=0;
function resize(){const bounds=shell.host.getBoundingClientRect(),scale=Math.min(1,bounds.height/450),W=bounds.width/scale,H=bounds.height/scale,mobile=bounds.width<650,subY=Math.min(H-115,H*.69);svg.style.setProperty('--scene-scale',scale);svg.style.setProperty('--label-size',`${(mobile?16:17)/scale}px`);svg.style.setProperty('--small-size',`${(mobile?12:13)/scale}px`);svg.style.setProperty('--id-size',`${12/scale}px`);layout={W,H,mobile,cx:W/2,dieWidth:Math.min(W*(mobile?.72:.64),760/scale),subW:Math.min(W*.88,1080/scale),subY,hoverY:Math.max(150,subY-(mobile?172:160)),boardH:mobile?40:48,r:mobile?16:22};svg.setAttribute('viewBox',`0 0 ${W} ${H}`);set('clip-box',{x:0,y:30,width:W,height:Math.max(0,H-30)});player?.redraw();}
const project=(y,z,a)=>[y*Math.cos(a)-z*Math.sin(a)+.32*(y*Math.sin(a)+z*Math.cos(a)),(y*Math.sin(a)+z*Math.cos(a))-.32*(y*Math.cos(a)-z*Math.sin(a))];
function chip(cx,cy,width,a){const pts=[[-1,-22,-12],[1,-22,-12],[1,22,-12],[-1,22,-12],[-1,-22,12],[1,-22,12],[1,22,12],[-1,22,12]].map(([x,y,z])=>{const p=project(y,z,a);return[cx+x*width/2,cy+p[0],p[1]];});const faces=[{ix:[0,1,5,4],color:colors.front},{ix:[3,2,6,7],color:colors.back},{ix:[0,1,2,3],color:colors.die},{ix:[4,5,6,7],color:colors.die}];faces.sort((a,b)=>a.ix.reduce((n,i)=>n+pts[i][2],0)-b.ix.reduce((n,i)=>n+pts[i][2],0));return faces.map(f=>`<polygon class="material" points="${f.ix.map(i=>pts[i].slice(0,2).join(',')).join(' ')}" fill="${f.color}"/>`).join('');}
function render(frame){
const s=stateAt(frame.local),{W,H,mobile,cx,dieWidth,subW,subY,hoverY,boardH,r}=layout;
const contacts=contactGeometry(s,layout),{cy,angle}=contacts[0],dcx=cx-28*(1-s.align),left=cx-dieWidth/2,right=cx+dieWidth/2,top=cy+26,subLeft=cx-subW/2,subRight=cx+subW/2;
set('assembly',{transform:`translate(${W*s.offset} 0)`,opacity:s.visible?1:0});el('batch-label').textContent=`第 ${frame.cycleId+1} 組`;set('batch-label',{x:W-16});
let sub=`<rect class="material" x="${subLeft}" y="${subY+8}" width="${subW}" height="${boardH}" rx="3" fill="#D8E4D8"/><path d="M${subLeft+12} ${subY+boardH-2}H${subRight-12}" stroke="#BCCDBE" fill="none"/>`;
contacts.forEach((c,i)=>{sub+=`<path d="M${c.padX} ${subY+7}V${subY+22+i%2*10}H${c.padX+dieWidth*.08}" fill="none" stroke="#B69D75" stroke-width="3"/><rect class="material" x="${c.padX-r*.95}" y="${subY}" width="${r*1.9}" height="8" rx="1" fill="${colors.pad}"/><rect x="${c.padX-r}" y="${subY-3}" width="${r*2}" height="3" rx="1.5" fill="${colors.flux}" opacity="${s.flux*s.residue}"/>`;});
sub+=text(cx,subY+boardH+36,'封裝基板','label','middle');el('substrate').innerHTML=sub;
el('alignment').innerHTML=(s.t>=7&&s.t<12)?contacts.map(c=>`<path class="guide" d="M${c.padX} ${cy+67}V${subY-8}"/>`).join(''):'';
el('chip-faces').innerHTML=chip(dcx,cy,dieWidth,angle);
let bumps='';contacts.forEach(c=>{const joined=s.place===1,path=joined?jointPath(c.x,top,subY,s.wet,r):jointPath(0,26,64,0,r),coef=-(Math.cos(angle)+.32*Math.sin(angle)),transform=joined?'':`transform="translate(${c.x} ${cy}) scale(1 ${coef})"`;bumps+=`<g ${transform}><path class="material" d="${path}" fill="${s.hot>.1?colors.hot:colors.solder}"/><rect class="material" x="${joined?c.x-r*.67:-r*.67}" y="${joined?cy+22:22}" width="${r*1.34}" height="4" fill="${colors.pad}"/></g>`;});
const faceDepth=project(-44,0,angle)[1];el('bumps-back').innerHTML=faceDepth<0&&s.flip<1?bumps:'';el('bumps-front').innerHTML=faceDepth>=0||s.flip===1?bumps:'';
const mark=project(-22,10,angle);el('identity-marks').innerHTML=`<path d="M${dcx-dieWidth/2+10} ${cy+mark[0]-3}h12v6h-12z" fill="#4B697E"/>`+contacts.map(c=>text(c.x,s.flip<.98?cy-76:cy-42,c.id,'point-id','middle')).join('');
const fillTop=subY-30;set('gap-white',{x:left-1,y:fillTop,width:dieWidth+2,height:30});el('joint-cutouts').innerHTML=contacts.map(c=>`<path d="${jointPath(c.padX,fillTop,subY,1,r)}"/>`).join('');
const front=left+s.fill*dieWidth,fpath=s.fill>0?`M${left} ${fillTop}H${front-5*Math.sin(Math.PI*s.fill)}Q${front+3*Math.sin(Math.PI*s.fill)} ${fillTop+15} ${front-5*Math.sin(Math.PI*s.fill)} ${subY}H${left}Z`:'';
set('fluid-body',{d:fpath,fill:s.cure>.5?colors.cured:colors.underfill});set('cure-texture',{d:fpath,opacity:s.cure});set('fluid-front',{d:s.fill>0&&s.fill<1?`M${front-5*Math.sin(Math.PI*s.fill)} ${fillTop}Q${front+3*Math.sin(Math.PI*s.fill)} ${fillTop+15} ${front-5*Math.sin(Math.PI*s.fill)} ${subY}`:''});
el('edge-fillets').innerHTML=s.fill>0?`<path d="M${left} ${fillTop}Q${left-7} ${subY-12} ${left-18} ${subY}H${left}Z" fill="${s.cure>.5?colors.cured:colors.underfill}" stroke="#739F90" opacity="${clamp(s.fill*10)}"/>${s.fill>.97?`<path d="M${right} ${fillTop}Q${right+7} ${subY-12} ${right+18} ${subY}H${right}Z" fill="${s.cure>.5?colors.cured:colors.underfill}" stroke="#739F90"/>`:''}`:'';
const needle=s.t>=18&&s.t<27,ny=subY-36-Math.max(0,1-(s.t-18)/.7)*38-Math.max(0,(s.t-26.5)/.5)*38,nx=left-20;
el('dispenser').innerHTML=needle?`<path d="M${nx-10} ${ny-55}h20v35l-7 20h-6l-7-20z" fill="#DCE4E9" stroke="#718592"/><path d="M${nx} ${ny}v${Math.max(0,subY-3-ny)}" stroke="${colors.underfill}" stroke-width="5"/>`:'';
const tracePath=`M${contacts[1].x-30} ${cy+12}H${contacts[1].x}V${subY+32}H${contacts[1].x+dieWidth*.08}`;
el('electric-path').innerHTML=s.t>=30?`<path d="${tracePath}" fill="none" stroke="#F7FCF5" stroke-width="6" opacity=".85"/><path d="${tracePath}" pathLength="1" fill="none" stroke="#527C8C" stroke-width="2.4" stroke-dasharray="${s.trace} 1"/>`:'';
let labels=text(dcx,cy+(s.flip>.1&&s.flip<.9?-62:6),'晶粒','label','middle');
const bottomLabel=s.t<7?'基板焊墊':s.t<12?'基板焊墊 · 一對一':s.t<18?'焊點形成':s.t<30?'焊點保留':'焊點連接電路';labels+=text(cx,subY+boardH+63,bottomLabel,'small-label','middle');
if(s.t<2.8){labels+=text(dcx,cy-101,'凸塊 · 接合面朝上','label','middle');labels+=text(dcx,cy+57,'背面','small-label','middle');}else if(s.t<7){labels+=text(dcx,cy-101,'凸塊跟著晶粒翻轉','label','middle');}else{labels+=text(dcx,cy-73,s.t<12?'凸塊 · 接合面朝下':'背面朝上','small-label','middle');}
if(s.t>=18&&s.t<33)labels+=text(cx,subY-169,s.t<27?'底填膠沿間隙前進':s.t<30?'底填膠固化中':'底填膠 · 保護與支撐','label','middle');el('object-labels').innerHTML=labels;
let note='';if(s.t>=7&&s.t<8.5)note='少量免清洗助焊劑';if(s.t>=12&&s.t<16)note='加熱 · 熔融與潤濕';if(s.t>=16&&s.t<18)note='冷卻 · 焊料凝固';if(s.t>=18&&s.t<27)note='毛細流動 · 從焊點前後繞行';if(s.t>=27&&s.t<30)note='加熱固化';if(s.t>=30&&s.t<33)note='亮線為連接路徑示意';el('process-note').innerHTML=note?text(cx,Math.max(52,hoverY-120),note,'small-label','middle'):'';
el('empty-label').textContent=s.visible?'':'下一組原料即將進場';set('empty-label',{x:cx,y:H/2});svg.dataset.stage=String(s.stage);svg.dataset.fill=String(s.fill);svg.dataset.cure=String(s.cure);svg.dataset.cycle=String(frame.cycleId);return{title:`${s.stage+1} · ${stages[s.stage].title}`,index:s.stage,count:stages.length};
}
function showNote(index){selected=index;const s=stages[index];el('step-select').value=String(index);el('step-heading').textContent=s.title;el('step-watch').textContent=s.watch;el('step-detail').textContent=s.detail;el('key-time').textContent=`代表畫面 ${s.key.toFixed(1)} 秒`;}
el('step-select').innerHTML=stages.map((s,i)=>`<option value="${i}">${i+1} · ${s.title}</option>`).join('');resize();
player=new ObserverPlayer({shell,durationMs:DURATION,overviewMs:31500,restartFromOverview:true,qa:location.hostname==='127.0.0.1'||location.hostname==='localhost',render,onInfo:()=>{showNote(stateAt(player.lastFrame.local).stage);player.openPanel();}});
new ResizeObserver(resize).observe(shell.host);el('step-select').addEventListener('change',e=>showNote(Number(e.target.value)));el('seek-step').addEventListener('click',()=>{player.seek(stages[selected].key*1000);player.closePanel();});showNote(0);
